briefs.props:
/** The order summary on the last step of a checkout. */
export interface Props {
  title: string;
  /** ISO 4217 code used for every amount, e.g. "USD". */
  currency: string;
  items: OrderItem[];
  promo: PromoField;
  subtotal: number;
  shipping: number;
  tax: number;
  total: number;
  /** A note to the customer, e.g. about delivery or returns. */
  note: string;
  /** Label of the pay button. */
  payLabel: string;
}

export interface OrderItem {
  id: string;
  image: ItemImage;
  name: string;
  /** The chosen variant, e.g. "Size M · Olive". */
  variant: string;
  quantity: number;
  /** Price of the line: unit price times quantity. */
  price: number;
}

export interface ItemImage {
  src: string;
  alt: string;
}

export interface PromoField {
  label: string;
  placeholder: string;
  /** Label of the button that applies the code. */
  applyLabel: string;
}

/** A dialog that confirms the deletion of a project. */
export interface Props {
  title: string;
  /** Explains what the action does. */
  body: string;
  /** The name of the project that will be deleted. */
  projectName: string;
  /** Heading of the list of consequences. */
  consequencesTitle: string;
  /** What deleting the project will do. */
  consequences: string[];
  /** The input where the user types the project's name to confirm. */
  confirmInput: ConfirmInput;
  cancelLabel: string;
  /** Label of the button that deletes the project. */
  confirmLabel: string;
}

export interface ConfirmInput {
  label: string;
  placeholder: string;
}

/** The recent orders panel of a store dashboard. */
export interface Props {
  title: string;
  /** Shown under the title. */
  summary: string;
  /** ISO 4217 code used for every amount, e.g. "USD". */
  currency: string;
  orders: Order[];
}

export type OrderStatus = 'paid' | 'pending' | 'refunded' | 'failed';

export interface Order {
  /** Order number shown to staff, e.g. "#10482". */
  id: string;
  customerName: string;
  email: string;
  status: OrderStatus;
  /** Order total, in the panel's currency. */
  amount: number;
  /** Already formatted for display, e.g. "Nov 11, 2026". */
  date: string;
}

/** One day of a person's calendar, as an agenda. */
export interface Props {
  /** Already formatted for display, e.g. "Thursday, 19 November". */
  dateLabel: string;
  /** In order of start time. */
  events: AgendaEvent[];
  /** Label of the button that adds an event. */
  addEventLabel: string;
}

export type TagColor = 'blue' | 'green' | 'amber' | 'red' | 'purple' | 'gray';

export interface EventTag {
  label: string;
  color: TagColor;
}

export interface AgendaEvent {
  id: string;
  /** Already formatted for display, e.g. "9:30 AM". */
  start: string;
  /** Already formatted for display, e.g. "10:00 AM". */
  end: string;
  title: string;
  location: string;
  /** The names of the people attending. */
  attendees: string[];
  tag: EventTag;
}

