/** The pricing section of a marketing page. */
export interface Props {
  heading: string;
  subheading: string;
  /** ISO 4217 code used for every price, e.g. "USD". */
  currency: string;
  plans: Plan[];
}

export interface Plan {
  /** Plan name, e.g. "Team". */
  name: string;
  /** Price per month, in the section's currency. */
  monthlyPrice: number;
  /** Who the plan is for. */
  description: string;
  /** Included features, in display order. */
  features: string[];
  /** Label of the plan's call-to-action button. */
  ctaLabel: string;
  /** Optional badge label, e.g. "Most popular". */
  badge?: string;
  /** True for the plan to recommend. */
  highlighted: boolean;
}

/** The product listing of a shop's category page. */
export interface Props {
  heading: string;
  /** e.g. "Showing 6 of 48 products" */
  resultsSummary: string;
  /** ISO 4217 code used for every price, e.g. "USD". */
  currency: string;
  products: Product[];
}

export interface Product {
  id: string;
  name: string;
  image: ProductImage;
  price: number;
  /** The price before the sale, present when the product is on sale. */
  originalPrice?: number;
  /** Average rating from 0 to 5. */
  rating: number;
  reviewCount: number;
  tags: string[];
  /** Label of the add-to-cart button. */
  ctaLabel: string;
}

export interface ProductImage {
  /** Path of the image, e.g. "/fe-assets/placeholder-1x1.svg". */
  src: string;
  /** Text alternative for the image. */
  alt: string;
}

/** The profile and notification settings section of an account settings page. */
export interface Props {
  title: string;
  description: string;
  displayName: TextField;
  email: TextField;
  timeZone: SelectField;
  notifications: NotificationSetting[];
  saveLabel: string;
  cancelLabel: string;
}

export interface TextField {
  label: string;
  /** The current value of the input. */
  value: string;
  /** Help text shown with the input. */
  help: string;
}

export interface SelectField {
  label: string;
  /** The value of the selected option. */
  value: string;
  options: SelectOption[];
}

export interface SelectOption {
  value: string;
  label: string;
}

export interface NotificationSetting {
  id: string;
  label: string;
  description: string;
  /** True when the notification is switched on. */
  enabled: boolean;
}

