briefs.props:
/** The key metric tiles at the top of a store analytics dashboard. */
export interface Props {
  title: string;
  /** The period the metrics cover, e.g. "Last 30 days". */
  periodLabel: string;
  /** ISO 4217 code used for currency values, e.g. "USD". */
  currency: string;
  metrics: Metric[];
}

export type MetricFormat = 'currency' | 'percent' | 'count';

export interface Metric {
  id: string;
  label: string;
  /** Raw value. For "percent", a fraction: 0.034 means 3.4%. */
  value: number;
  format: MetricFormat;
  /** Change against the previous period, as a fraction: -0.052 means -5.2%. */
  change: number;
  caption: string;
}

/** A tabbed section of a documents page: the tabs and the active tab's panel. */
export interface Props {
  tabs: Tab[];
  /** The panel of the active tab. */
  panel: Panel;
}

export interface Tab {
  id: string;
  label: string;
  /** The number of documents behind the tab. */
  count: number;
  /** True for the tab whose panel is shown. */
  active: boolean;
}

export interface Panel {
  heading: string;
  description: string;
  items: PanelItem[];
}

export interface PanelItem {
  id: string;
  /** The document's name. */
  name: string;
  /** Shown under the name, e.g. who the document is waiting on. */
  detail: string;
}

